"""DGP10 final ledger sidecar (UNSUPERVISED by necessity: it reads the ledger after the last supervised receipt): every receipt, by scope, totals, the receipts written AFTER the analyzer's CHARGES.json (packaging / validation / restore test),
unique-id reconciliation. usage: dgp10_sidecar.py"""
import os, json, time
RD = os.environ.get('DGP10_RD', '/Users/adis/Workspace/pgm-records/code/runs/mdi_2026-10-28/DGP10_QUERY_RESPONSE')
rows = [json.loads(l) for l in open(os.path.join(RD, 'DGP10_LEDGER.jsonl'))]; rc = [r for r in rows if r.get('kind') == 'RECEIPT']; ch = json.load(open(os.path.join(RD, 'CHARGES.json'))) if os.path.exists(os.path.join(RD, 'CHARGES.json')) else {}; bud = json.load(open(os.path.join(RD, 'BUDGET_DECLARATION.json')))
after = [r for r in rc if (r.get('start_utc') or '') >= (ch.get('utc') or '9')]
out = dict(utc=time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()), ceiling_s=bud['ceiling_s'], total_s=round(sum(r['wall_s'] for r in rc), 3), n_receipts=len(rc), unique_jids=(len({r['jid'] for r in rc}) == len(rc)), by_scope_s={s: round(sum(r['wall_s'] for r in rc if r['scope'] == s), 3) for s in sorted({r['scope'] for r in rc})}, by_outcome={o: sum(1 for r in rc if r['outcome'] == o) for o in sorted({r['outcome'] for r in rc})},
           charges_json_total_s=ch.get('total_s'), charges_json_utc=ch.get('utc'), receipts_after_charges_json=[dict(job=r['job'], wall_s=round(r['wall_s'], 3), outcome=r['outcome'], start_utc=r['start_utc']) for r in after], after_total_s=round(sum(r['wall_s'] for r in after), 3), within_ceiling=(sum(r['wall_s'] for r in rc) <= bud['ceiling_s']), spawned_without_receipt=[s['jid'] for s in rows if s.get('kind') == 'SPAWNED' and not any(r['jid'] == s['jid'] for r in rc)],
           note='UNSUPERVISED sidecar (it reads the ledger after the last supervised receipt; its own cost is labor, not compute); the external closure manifest hashes this file')
json.dump(out, open(os.path.join(RD, 'DGP10_FINAL_LEDGER_SIDECAR.json'), 'w'), indent=1); print(json.dumps({k: v for k, v in out.items() if k not in ('receipts_after_charges_json',)}))
